insert into public.technical_questions
  (id, topic, prompt, options, answer_index, explanation, difficulty, source_file, source_location, source)
values
(1, 'Operating Systems', 'A process waiting for an I/O operation to complete is in which state?', '["Ready","Running","Waiting (blocked)","Terminated"]'::jsonb, 2, 'States: New → Ready → Running → Waiting → Terminated.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'OS4', 'provided_resource'),
(2, 'Operating Systems', 'Which scheduling algorithm gives the minimum average waiting time?', '["FCFS","SJF","Round Robin","Priority"]'::jsonb, 1, 'SJF is optimal for average waiting time but needs burst times in advance.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'OS7', 'provided_resource'),
(3, 'Operating Systems', 'How many necessary conditions (Coffman conditions) must hold simultaneously for a deadlock?', '["2","3","4","5"]'::jsonb, 2, 'Mutual exclusion, hold and wait, no preemption, circular wait.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'OS11', 'provided_resource'),
(4, 'Operating Systems', 'Belady''s anomaly (more frames causing more page faults) occurs in which page replacement algorithm?', '["LRU","Optimal","FIFO","LFU"]'::jsonb, 2, 'Stack algorithms like LRU and Optimal do not suffer from it.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'OS15', 'provided_resource'),
(5, 'Operating Systems', 'Which system call creates a new process in UNIX/Linux?', '["exec()","fork()","wait()","exit()"]'::jsonb, 1, 'fork() duplicates the process; exec() replaces its program.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'OS21', 'provided_resource'),
(6, 'Operating Systems', 'Which of these is NOT a requirement of a critical section solution?', '["Mutual exclusion","Progress","Bounded waiting","Maximum CPU usage"]'::jsonb, 3, 'The three requirements: mutual exclusion, progress, bounded waiting.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'OS24', 'provided_resource'),
(7, 'Operating Systems', 'Which memory allocation strategy allocates the smallest free block that is large enough?', '["First fit","Best fit","Worst fit","Next fit"]'::jsonb, 1, 'Best fit minimises wasted space but leaves tiny unusable holes.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'OS30', 'provided_resource'),
(8, 'Networking', 'What is the default port number of HTTPS?', '["80","21","443","25"]'::jsonb, 2, 'HTTP uses 80; HTTPS (HTTP over TLS) uses 443.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'B5', 'provided_resource'),
(9, 'Networking', 'Which protocol translates a domain name like www.accenture.com into an IP address?', '["DHCP","DNS","ARP","FTP"]'::jsonb, 1, 'DNS (Domain Name System) resolves names to IP addresses.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'B6', 'provided_resource'),
(10, 'Networking', 'Which device forwards frames based on MAC addresses?', '["Hub","Router","Switch","Repeater"]'::jsonb, 2, 'A switch maintains a MAC address table and forwards frames only to the destination port.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'B16', 'provided_resource'),
(11, 'Networking', 'Which port number does SSH use?', '["21","22","23","25"]'::jsonb, 1, 'SSH = 22, Telnet = 23, FTP = 20/21, SMTP = 25.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'B21', 'provided_resource'),
(12, 'Networking', 'Which HTTP status code indicates a successful request?', '["200","301","404","500"]'::jsonb, 0, '2xx = success, 3xx = redirection, 4xx = client error, 5xx = server error.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'B23', 'provided_resource'),
(13, 'Networking', 'Users can ping 8.8.8.8 successfully but cannot open www.google.com in the browser. What is the most likely problem?', '["Faulty network cable","DNS resolution failure","Wrong MAC address","Switch failure"]'::jsonb, 1, 'Connectivity by IP works, so only name resolution is failing.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'S2', 'provided_resource'),
(14, 'Cloud', 'Which cloud model gives the customer control over the OS but not the physical hardware?', '["SaaS","PaaS","IaaS","FaaS"]'::jsonb, 2, 'IaaS (e.g. AWS EC2): you manage OS, runtime and apps; provider manages hardware.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'A17', 'provided_resource'),
(15, 'Cloud', 'A startup wants to deploy its application without managing servers, operating systems or runtimes. Which cloud model fits?', '["IaaS","PaaS","On-premises","Colocation"]'::jsonb, 1, 'PaaS (e.g. Google App Engine, Heroku) lets developers just deploy code.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'S11', 'provided_resource'),
(16, 'Cloud', 'Which cloud service model delivers ready-to-use applications over the internet, such as web-based email?', '["IaaS","PaaS","SaaS","DaaS"]'::jsonb, 2, 'SaaS examples: Gmail, Microsoft 365, Salesforce.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'AP1', 'provided_resource'),
(17, 'Cloud', 'Which of the following is NOT an essential characteristic of cloud computing?', '["On-demand self-service","Broad network access","Rapid elasticity","Fixed capacity provisioning"]'::jsonb, 3, 'NIST lists on-demand self-service, broad network access, resource pooling, rapid elasticity and measured service.', 'moderate', 'TalentShine_Accenture_Networking_Handout.docx', 'AP5', 'provided_resource'),
(18, 'DevOps', 'A team automatically builds and tests every integrated code change. What practice?', '["Continuous Integration","Manual deployment","Waterfall planning","Ad hoc testing"]'::jsonb, 0, 'Answer stated in the supplied DevOps MCQ notes.', 'moderate', '01_Accenture_DevOps_MCQ_Master_Notes.docx', 'Question DEVOPS1', 'provided_resource'),
(19, 'DevOps', 'Which Kubernetes object gives stable access to changing pods?', '["Service","Volume","Image","Secret"]'::jsonb, 0, 'Answer stated in the supplied DevOps MCQ notes.', 'moderate', '01_Accenture_DevOps_MCQ_Master_Notes.docx', 'Question DEVOPS2', 'provided_resource'),
(20, 'DevOps', 'What is a running instance of a Docker image?', '["Container","Repository","Cluster","Pipeline"]'::jsonb, 0, 'Answer stated in the supplied DevOps MCQ notes.', 'moderate', '01_Accenture_DevOps_MCQ_Master_Notes.docx', 'Question DEVOPS3', 'provided_resource'),
(21, 'Security', 'What does the CIA triad in information security stand for?', '["Control, Integrity, Access","Confidentiality, Integrity, Availability","Confidentiality, Identity, Authentication","Cyber, Internet, Access"]'::jsonb, 1, 'The three core goals of security: keep data secret, correct and accessible.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'CS1', 'provided_resource'),
(22, 'Security', 'The main function of a firewall is to:', '["Remove viruses from files","Monitor and filter network traffic based on security rules","Speed up internet","Back up data"]'::jsonb, 1, 'A firewall allows or blocks traffic according to rules.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'CS10', 'provided_resource'),
(23, 'Security', 'A tester enters '' OR ''1''=''1 in a login form''s username field and logs in without a valid password. Which vulnerability exists?', '["XSS","SQL injection","CSRF","Buffer overflow"]'::jsonb, 1, 'Fix with parameterised queries and input validation.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'CSC4', 'provided_resource'),
(24, 'Security', 'A blog''s comment box lets a user post a script that runs in the browser of every visitor who views the page. Which attack is this?', '["Stored XSS","Reflected XSS","SQL injection","DDoS"]'::jsonb, 0, 'The script is stored on the server, so it affects every visitor.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'CSC5', 'provided_resource'),
(25, 'Software Design', 'Which of the following is NOT one of the four pillars of OOP?', '["Encapsulation","Inheritance","Polymorphism","Compilation"]'::jsonb, 3, 'The four pillars are Encapsulation, Abstraction, Inheritance and Polymorphism.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'OB1', 'provided_resource'),
(26, 'Software Design', 'Which access modifier is the most restrictive?', '["public","protected","default","private"]'::jsonb, 3, 'Private members are accessible only inside the same class.', 'moderate', 'TalentShine_Accenture_CS_Fundamentals_Handout.docx', 'OB7', 'provided_resource'),
(27, 'Database / SQL', 'Which clause is used to filter groups after aggregation?', '["WHERE","HAVING","ORDER BY","LIMIT"]'::jsonb, 1, 'WHERE filters rows before grouping; HAVING filters groups.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'SQ1', 'provided_resource'),
(28, 'Database / SQL', 'Which JOIN returns all rows from the left table and matching rows from the right table?', '["INNER JOIN","LEFT JOIN","RIGHT JOIN","CROSS JOIN"]'::jsonb, 1, 'Unmatched right-side columns are filled with NULL.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'SQ3', 'provided_resource'),
(29, 'Database / SQL', 'Which is the correct way to check for missing values?', '["WHERE DEPTID = NULL","WHERE DEPTID IS NULL","WHERE DEPTID == NULL","WHERE DEPTID EQUALS NULL"]'::jsonb, 1, 'Comparisons with NULL using = are never true; use IS NULL / IS NOT NULL.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'SQ4', 'provided_resource'),
(30, 'Database / SQL', 'Which wildcard matches exactly ONE character in a LIKE pattern?', '["%","_","*","?"]'::jsonb, 1, '% matches zero or more characters.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'SQ5', 'provided_resource'),
(31, 'Database / SQL', 'Which normal form removes transitive dependencies?', '["1NF","2NF","3NF","None"]'::jsonb, 2, '3NF: non-key columns must depend only on the key.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'SQ14', 'provided_resource'),
(32, 'Web Technologies', 'Which HTML tag creates a hyperlink?', '["<link>","<a>","<href>","<url>"]'::jsonb, 1, '<a href="...">. <link> connects external resources like CSS.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'FE1', 'provided_resource'),
(33, 'Web Technologies', 'Which is the correct CSS selector for an element with id="tiger-image"?', '[".tiger-image","#tiger-image","tiger-image","*tiger-image"]'::jsonb, 1, '# = id, . = class.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'FE4', 'provided_resource'),
(34, 'Web Technologies', 'In the CSS box model, which property creates space INSIDE the border?', '["margin","padding","outline","spacing"]'::jsonb, 1, 'Order from inside out: content → padding → border → margin.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'FE5', 'provided_resource'),
(35, 'Web Technologies', 'Which JavaScript method selects an element by its id?', '["document.querySelectorAll()","document.getElementById()","document.getElementsByClassName()","document.findId()"]'::jsonb, 1, 'querySelector(''#id'') also works.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'FE10', 'provided_resource'),
(36, 'Web Technologies', 'Which HTML5 attribute makes an input field mandatory?', '["validate","required","mandatory","needed"]'::jsonb, 1, 'The browser blocks form submission while it is empty.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'FE17', 'provided_resource'),
(37, 'Programming Fundamentals', 'What is the output? for (int i = 0; i < 5; i++) { if (i == 3) continue; System.out.print(i); }', '["0123","0124","012","01234"]'::jsonb, 1, 'continue skips printing 3 only.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'OM3', 'provided_resource'),
(38, 'Programming Fundamentals', 'Python: what is the output? a = [1, 2, 3]; b = a; b.append(4); print(len(a))', '["3","4","Error","1"]'::jsonb, 1, 'b refers to the same list object as a.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'OM4', 'provided_resource'),
(39, 'Programming Fundamentals', 'Python: what is the output? print(7 // 2, 7 % 2, 2 ** 3)', '["3.5 1 6","3 1 8","3 1 6","4 1 8"]'::jsonb, 1, '// is floor division, % is remainder, ** is power.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'OM6', 'provided_resource'),
(40, 'Programming Fundamentals', 'What is the time complexity of searching a key in a HashMap on average?', '["O(1)","O(log n)","O(n)","O(n log n)"]'::jsonb, 0, 'Worst case can be O(n) with many collisions (Java 8+ improves it to O(log n) using trees).', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'OM7', 'provided_resource'),
(41, 'Programming Fundamentals', 'Python: what is the output? s = "Accenture"; print(s[::-1][:3])', '["Acc","eru","ert","cce"]'::jsonb, 1, 'Reversed string is ''erutneccA''; first 3 characters are ''eru''.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'OM10', 'provided_resource'),
(42, 'Programming Fundamentals', 'Java: what is the output? int[] a = {3, 1, 2}; Arrays.sort(a); System.out.println(a[0] + a[2]);', '["4","5","3","6"]'::jsonb, 0, 'Sorted array is [1, 2, 3]; 1 + 3 = 4.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'OM11', 'provided_resource'),
(43, 'Programming Fundamentals', 'What is the time complexity of the Two Sum solution using a HashMap?', '["O(n²)","O(n log n)","O(n)","O(1)"]'::jsonb, 2, 'One pass with O(1) average lookups.', 'moderate', 'TalentShine_Accenture_Coding_SQL_Frontend_Handout .docx', 'OM14', 'provided_resource'),
(44, 'Other Topics', 'Which shortcut inserts a page break?', '["Shift+Enter","Ctrl+Enter","Alt+Enter","Ctrl+Shift+B"]'::jsonb, 1, 'Answer verified against the supplied Office question bank.', 'moderate', 'TalentShine_MS_Office_Handout_and_MCQ_Bank.docx', 'WORD1', 'provided_resource'),
(45, 'Other Topics', 'How many rows does an Excel 2007+ worksheet have?', '["65,536","1,048,576","16,384","1,000,000"]'::jsonb, 1, 'Answer verified against the supplied Office question bank.', 'moderate', 'TalentShine_MS_Office_Handout_and_MCQ_Bank.docx', 'EXCEL1', 'provided_resource')
